  val command: String,
  val callback: Long,
  val error: Long,
  private val sendResponse: (callback: Long, data: String) -> Unit,
  private val argsJson: String,
  private val jsonMapper: ObjectMapper
) {
  fun getRawArgs(): String {
    return argsJson
  }

  fun getArgs(): JSObject {
